<script setup>import AppLayout from '../Layouts/AppLayout.vue';import SectionTitle from '../Components/SectionTitle.vue';import {router} from '@inertiajs/vue3';import {ref} from 'vue';import {Send,CheckCircle2,Sparkles,ArrowRight} from 'lucide-vue-next';const sent=ref(false);const form=ref({participant_name:'',role:'',rating:5,pain_point:'',suggestion:'',would_continue:true,notes:''});const submit=()=>router.post('/prototype/feedback',form.value,{onSuccess:()=>{sent.value=true;form.value={participant_name:'',role:'',rating:5,pain_point:'',suggestion:'',would_continue:true,notes:''}}});</script>
<template><AppLayout><SectionTitle eyebrow="03 · REAL-WORLD TEST" title="Prototype feedback lab" description="Use this screen during a real usability session. Ask the participant to complete a small task, then record what changed."><span class="badge purple">USER TESTING</span></SectionTitle><div class="prototype-grid"><div class="panel prototype-preview"><div class="preview-top"><div class="mini-logo">IP</div><span>Participant workspace</span><span class="preview-dot"></span></div><div class="preview-body"><span class="eyebrow">TODAY'S FOCUS</span><h3>Build one small piece of career evidence.</h3><p>Choose one action that moves your future forward and record the outcome.</p><div class="action-card"><div class="action-number">01</div><div><b>Create a 7-day action plan</b><span>Define one goal, three actions and one measurable outcome.</span></div><CheckCircle2 :size="20"/></div><div class="action-card muted"><div class="action-number">02</div><div><b>Capture a learning outcome</b><span>Write what you learned and attach evidence.</span></div><ArrowRight :size="20"/></div></div></div><div class="panel feedback-panel"><div v-if="!sent"><div class="panel-head"><div><span class="eyebrow">SESSION FORM</span><h3>Capture feedback</h3><p class="privacy-hint">Get consent first. Use an anonymous code such as P01; do not record identifying details.</p></div><Sparkles :size="20"/></div><div class="form-grid"><label>Participant code<input v-model="form.participant_name" placeholder="P01 (do not enter a real name)"></label><label>Role<input v-model="form.role" placeholder="Developer / Student"></label><label>Rating <span class="rating-value">{{form.rating}}/5</span><input v-model="form.rating" type="range" min="1" max="5"></label><label>Would continue? <select v-model="form.would_continue"><option :value="true">Yes</option><option :value="false">Not yet</option></select></label><label class="full-field">Main pain point<textarea v-model="form.pain_point" placeholder="What was difficult?"></textarea></label><label class="full-field">Suggestion<textarea v-model="form.suggestion" placeholder="What should change?"></textarea></label><label class="full-field">Notes<textarea v-model="form.notes"></textarea></label></div><button class="primary-btn full" @click="submit"><Send :size="16"/> Save feedback</button></div><div v-else class="success-state"><CheckCircle2 :size="46"/><span class="eyebrow">CAPTURED</span><h3>Feedback saved.</h3><p>Thank the participant and continue with the next task test.</p><button class="secondary-btn" @click="sent=false">Add another session</button></div></div></div></AppLayout></template>
